
  (()=>{
    const root=document.getElementById('forma-cards'),app=root.querySelector('.fc-app');
    const q=s=>root.querySelector(s),qa=s=>[...root.querySelectorAll(s)];
    const icon=n=>`<i data-lucide="${n}" aria-hidden="true"></i>`;
    const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    const reduce=()=>window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const areas=[
      {name:'Diseño',desc:'Cómo se ve y se usa',icon:'pen-tool',task:'Diseñar pantallas claras y coherentes.',needs:'Plan y preferencias del usuario.',delivery:'Pantallas, colores y tipografía acordados.',test:'El recorrido se entiende y se puede leer.',workers:['Pantallas y espacios','Colores y tipografía']},
      {name:'Funcionamiento',desc:'Qué hace y cómo',icon:'workflow',task:'Construir las funciones acordadas.',needs:'Plan común y diseño aprobado.',delivery:'Funciones y tratamiento de errores.',test:'Cada acción produce el resultado esperado.',workers:['Funciones principales','Datos y validaciones']},
      {name:'Pruebas y calidad',desc:'Que todo encaje',icon:'scan-line',task:'Comprobar el conjunto y registrar defectos.',needs:'Criterios y entregas de las otras áreas.',delivery:'Pruebas, hallazgos y verificación de correcciones.',test:'Cada aprobación tiene una comprobación.',workers:['Probar el recorrido','Comprobar correcciones']}
    ];
    const banks={
      torneo:[{id:'t1',title:'Una clasificación pública.',text:'Mostrar quién gana más partidas y actualizar la clasificación al terminar cada ronda.',why:'Da continuidad a los torneos, aunque amplía la primera versión.',glyph:'trophy'},{id:'t2',title:'Que nadie se pierda su partida.',text:'Añadir un recordatorio de la hora y del rival antes de empezar cada encuentro.',why:'Ayuda a los participantes a llegar a tiempo.',glyph:'bell-ring'},{id:'t3',title:'Apuntarse en un paso.',text:'Un formulario corto con nombre y disponibilidad, sin pedir datos que no necesites.',why:'Hace más fácil participar desde el móvil.',glyph:'user-round-plus'},{id:'t4',title:'Las reglas, siempre a mano.',text:'Una ficha breve con las reglas del torneo junto al botón de inscripción.',why:'Evita dudas antes de apuntarse.',glyph:'book-open'}],
      tienda:[{id:'s1',title:'Elegir sin adivinar.',text:'Incluir una guía de tallas y medidas en cada producto.',why:'Ayuda a decidir antes de comprar.',glyph:'ruler'},{id:'s2',title:'Ver lo que importa.',text:'Mostrar precio, disponibilidad y detalles principales antes del botón de compra.',why:'Aclara la decisión del cliente.',glyph:'tag'},{id:'s3',title:'Guardar para después.',text:'Permitir guardar productos favoritos para compararlos más tarde.',why:'Es útil cuando el visitante todavía no quiere comprar.',glyph:'bookmark'}],
      estudio:[{id:'e1',title:'Sesiones a tu ritmo.',text:'Dividir el estudio en bloques cortos y dejar elegir su duración.',why:'Se adapta a distintos hábitos de estudio.',glyph:'timer'},{id:'e2',title:'Practicar lo que cuesta.',text:'Guardar las preguntas falladas para repasarlas después.',why:'Concentra el repaso en las dificultades.',glyph:'repeat-2'},{id:'e3',title:'Un objetivo cada día.',text:'Proponer una pequeña tarea diaria elegida por el estudiante.',why:'Hace más concreto por dónde empezar.',glyph:'calendar-check'}],
      general:[{id:'g1',title:'Una primera versión pequeña.',text:'Elegir una sola acción principal y hacer que se pueda completar de principio a fin.',why:'Permite probar pronto si la idea resulta útil.',glyph:'focus'},{id:'g2',title:'Una bienvenida que orienta.',text:'Explicar con una frase qué puede hacer la persona y mostrarle el primer paso.',why:'Ayuda a quien llega sin conocer tu proyecto.',glyph:'signpost'},{id:'g3',title:'Decidir con una muestra.',text:'Preparar dos propuestas de una pantalla importante antes de desarrollar el conjunto.',why:'Permite elegir el estilo con algo concreto.',glyph:'panels-top-left'}]
    };
    const state={idea:'Una web para organizar torneos entre amigos.',answer:'',topic:'torneo',view:'ideas',phase:0,selected:'super',approved:[false,false,false],added:[],discarded:[],notice:'',result:'',worker:null,versions:1,versionsConfirmed:false,variation:'Diseño y distribución',preferences:'',exportTarget:'claude'};
    const tour={open:false,playing:false,index:0,token:0,snapshot:null};
    const wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));
    function identify(t){if(/torne|partida|jugador/i.test(t))return'torneo';if(/tienda|vend|producto|camiseta/i.test(t))return'tienda';if(/estudi|repas|examen|aprend/i.test(t))return'estudio';return'general'}
    function available(){return banks[state.topic].filter(c=>!state.discarded.includes(c.id)&&!state.added.some(a=>a.id===c.id))}
    function save(){if(tour.open)return;try{localStorage.setItem('forma-project-v1',JSON.stringify({...state,notice:''}))}catch{state.notice='No se pudo guardar en este navegador. Puedes exportar tu trabajo.'}}
    function icons(){if(globalThis.lucide)lucide.createIcons({attrs:{width:16,height:16}})}
    function button(label,act,glyph='arrow-up-right',strong=false){return`<button type="button" class="fc-button cursor-interaction ${strong?'fc-strong':''}" data-act="${act}"><span>${label}</span>${icon(glyph)}</button>`}
    function heading(name,sub,glyph='compass',badge=''){return`<div class="fc-panel-head"><span class="fc-node-icon">${icon(glyph)}</span><div><strong>${name}</strong><small>${sub}</small></div>${badge?`<span class="fc-label">${badge}</span>`:''}</div>`}
    function addedList(){return state.added.length?`<ul class="fc-added-list">${state.added.map(x=>`<li>${icon('check')}<span>${safe(x.title)}</span></li>`).join('')}</ul>`:''}
    function render(){renderMap();renderPanel();renderTour();q('[data-act="export"]').disabled=!state.phase||!state.approved.every(Boolean)||!state.versionsConfirmed;icons()}
    function renderMap(){const all=state.approved.every(Boolean)&&state.versionsConfirmed;q('.fc-map-status').textContent=state.phase?all?(state.result==='done'?'Recorrido terminado':'Encargos preparados'):`${state.approved.filter(Boolean).length} de 3 áreas aprobadas`:'Primero, los cimientos';
      q('.fc-graph').innerHTML=`<button class="fc-node fc-super cursor-interaction" data-node="super" type="button" aria-pressed="${state.selected==='super'}"><span class="fc-node-icon">${icon('orbit')}</span><span class="fc-node-copy"><strong>Supercoordinador</strong><small>${state.phase?'Plan aprobado':'Da forma a tu idea'}</small></span>${icon(state.phase?'check':'sparkles')}</button><div class="fc-stem"></div><div class="fc-cross"></div><div class="fc-branches">${areas.map((a,i)=>`<div class="fc-branch"><div class="fc-stem"></div><button class="fc-node cursor-interaction" data-node="${i}" type="button" aria-pressed="${state.selected===i}" aria-disabled="${!state.phase}"><span class="fc-node-icon">${icon(state.phase?(state.approved[i]?'check':a.icon):'lock-keyhole')}</span><span class="fc-node-copy"><strong>${a.name}</strong><small>${state.phase?(state.approved[i]?'Aprobado':a.desc):'Después del plan'}</small></span></button><div class="fc-leaves">${all?a.workers.map((w,j)=>`<button class="fc-leaf cursor-interaction" type="button" data-worker="${i}-${j}">${icon('user-round')}<span>${w}</span></button>`).join(''):`<button class="fc-leaf" type="button" disabled>${icon('lock-keyhole')}<span>Trabajadores pendientes</span></button>`}</div></div>`).join('')}</div>`;
      qa('[data-node]').forEach(b=>b.onclick=()=>{if(tour.playing)return;if(b.dataset.node!=='super'&&!state.phase){state.notice='Primero concreta y aprueba el plan con el supercoordinador.';renderPanel();return}state.selected=b.dataset.node==='super'?'super':Number(b.dataset.node);state.view='overview';state.notice='';render();save()});qa('[data-worker]').forEach(b=>b.onclick=()=>{if(tour.playing)return;const[i,j]=b.dataset.worker.split('-').map(Number);state.selected=i;state.worker=j;state.view='worker';state.notice='';render();save()});
      q('.fc-map-caption-text').textContent=state.phase?'Reparto ilustrativo. El equipo real se ajustará a cada proyecto.':'Tres áreas esenciales. Otros departamentos dependerán de tu idea.';
    }
    function renderPanel(){let html='';const panel=q('.fc-panel');if(state.selected==='super'){
      html+=heading('Supercoordinador','La dirección de tu proyecto','orbit',state.phase?'Plan listo':'Tu idea');
      if(state.view==='start'||(!state.idea&&state.view==='overview'))html+=`<h3>¿Qué te gustaría<br>poner en marcha?</h3><p>Escribe lo que tienes en mente. Podemos darle forma juntos.</p><label class="fc-field">Tu punto de partida<textarea rows="4" data-field="idea" placeholder="Quiero crear…">${safe(state.idea)}</textarea></label><div class="fc-actions">${button('Desarrollar mi idea','develop','arrow-right',true)}${button('Necesito ideas para empezar','ideas','sparkles')}</div><p class="fc-fine">En esta propuesta puedes explorar recomendaciones preparadas para torneos, tiendas y estudio.</p>`;
      else if(state.view==='questions'){
        const question=state.topic==='torneo'?'¿Los participantes se apuntarán solos?':state.topic==='tienda'?'¿Se comprará en la web o solo se verá el catálogo?':state.topic==='estudio'?'¿Quieres organizar el estudio o practicar preguntas?':'¿Quién utilizará tu proyecto y qué necesita conseguir?';
        html+=`<button class="fc-back cursor-interaction" type="button" data-act="back">${icon('arrow-left')}Tu idea</button><h3>${question}</h3><p>La respuesta ayuda a concretar las funciones y el equipo.</p><label class="fc-field">Tu respuesta<textarea rows="3" data-field="answer" placeholder="Cuéntame cómo lo imaginas…">${safe(state.answer)}</textarea></label><div class="fc-actions">${button('Guardar y seguir','answer','arrow-right',true)}${button('Ideas para mi proyecto','ideas','sparkles')}</div>`;
      }else if(state.view==='ideas'){
        const card=available()[0];html+=`<button class="fc-back cursor-interaction" type="button" data-act="back">${icon('arrow-left')}Tu idea</button><h3>Ideas para tu idea.</h3><p>Quédate con lo que encaje. Lo demás, déjalo pasar.</p><div class="fc-deck">${card?`<article class="fc-idea-card cursor-interaction" aria-label="Recomendación: ${safe(card.title)}"><div class="fc-card-top"><span>UNA POSIBILIDAD PARA TI</span>${icon('sparkles')}</div><div class="fc-card-symbol">${icon(card.glyph)}</div><h4>${card.title}</h4><p>${card.text}</p><div class="fc-card-link">${card.why}</div><span class="fc-swipe-label" aria-hidden="true"></span></article>`:`<div class="fc-idea-card fc-empty-card">${icon('check-check')}<h4>Ya has explorado este mazo.</h4><p>Revisa las ideas que has añadido o vuelve al plan.</p></div>`}</div>${card?`<div class="fc-deck-actions"><button class="fc-choice cursor-interaction" type="button" data-act="discard">${icon('x')}Descartar</button><button class="fc-choice fc-strong cursor-interaction" type="button" data-act="accept">${icon('plus')}Añadir a mi idea</button></div><p class="fc-deck-hint">Desliza ← para descartar · para añadir →</p>`:''}<p class="fc-decision" role="status">${safe(state.notice)}</p>${state.added.length?`<details class="fc-sheet"><summary class="cursor-interaction">${state.added.length} ${state.added.length===1?'idea añadida':'ideas añadidas'}</summary>${addedList()}</details>`:''}<p class="fc-fine">Mazo preparado para esta maqueta. La herramienta conectada propondrá nuevas ideas según lo que cuentes.</p>`;
      }else if(state.view==='plan')html+=`<h3>Esto es lo que<br>vamos a construir.</h3><div class="fc-saved"><small>TU IDEA</small>${safe(state.idea)}</div><details class="fc-sheet" open><summary class="cursor-interaction">Cimientos del proyecto</summary><dl><dt>Uso</dt><dd>${safe(state.answer||'Pendiente de concretar con el usuario.')}</dd><dt>Alcance</dt><dd>Una primera versión pequeña y comprobable.</dd><dt>Validación</dt><dd>Completar el recorrido principal y comprobar errores.</dd></dl>${addedList()}</details><div class="fc-actions">${button('Aprobar y preparar el equipo','team','git-branch',true)}${button('Seguir elaborando','back','arrow-left')}</div><p class="fc-fine">Reparto ilustrativo: diseño, funcionamiento y calidad. En el producto real se añadirán las áreas necesarias.</p>`;
      else if(state.view==='versions')html+=`<h3>¿Cuántas propuestas<br>quieres explorar?</h3><p>Son versiones del resultado, no modelos de IA. Puedes elegir una, comparar varias o combinar lo que te guste.</p><label class="fc-field">Número de propuestas<input type="number" data-field="versions" min="1" max="10" step="1" value="${state.versions}"></label><label class="fc-field">¿Qué quieres que varíe?<textarea rows="2" data-field="variation">${safe(state.variation)}</textarea></label><p class="fc-fine">Más propuestas requieren más trabajo y consumo cuando conectes la ejecución. El límite de 10 pertenece a este prototipo.</p><div class="fc-actions">${button('Confirmar propuestas y preparar encargos','versions-save','check',true)}${button('Volver al plan','plan','arrow-left')}</div>`;
      else if(state.view==='result')html+=`<h3>${state.result==='issue'?'Un detalle necesita atención.':state.result==='fixed'?'Corregido. Falta comprobarlo.':'Las piezas ya encajan.'}</h3><div class="fc-saved"><small>${state.result==='issue'?'HALLAZGO DE CALIDAD':state.result==='fixed'?'CORRECCIÓN RECIBIDA':'REVISIÓN DEL CONJUNTO'}</small>${state.result==='issue'?'El formulario permite enviar la inscripción sin nombre. Funcionamiento debe corregirlo.':state.result==='fixed'?'El trabajador ha añadido la validación. Calidad vuelve a intentar una inscripción sin nombre.':'En la demostración, el diseño y las funciones coinciden con el plan y la corrección ha pasado su comprobación.'}</div><div class="fc-actions">${state.result==='issue'?button('Pedir corrección concreta','fix','repeat-2',true):state.result==='fixed'?button('Comprobar la corrección','verify','scan-line',true):button('Ver el resumen del proyecto','plan','file-text',true)}</div><p class="fc-fine">Resultado simulado para mostrar el circuito. No se ha ejecutado ni probado una aplicación real.</p>`;
      else html+=`<h3>Tu idea está<br>tomando forma.</h3><div class="fc-saved"><small>TU PUNTO DE PARTIDA</small>${safe(state.idea)}<button class="fc-back cursor-interaction" type="button" data-act="edit" style="margin:10px 0 0">${icon('pencil')}Cambiar mi idea</button></div>${addedList()}<div class="fc-actions">${button('Hazme preguntas','questions','messages-square')}${button('Ideas para mi proyecto','ideas','sparkles')}${button(state.approved.every(Boolean)?'Número de propuestas':'Revisar y seguir',state.approved.every(Boolean)?'versions':'plan','arrow-right',true)}</div>`;
    }else{const i=state.selected,a=areas[i];html+=heading(a.name,a.desc,a.icon,state.approved[i]?'Aprobado':'Por concretar');
      if(state.view==='preferences')html+=`<button class="fc-back cursor-interaction" type="button" data-act="back">${icon('arrow-left')}Plan de diseño</button><h3>¿Qué aspecto<br>te gustaría darle?</h3><p>Puedes describir un estilo o contar qué referencias te gustan.</p><label class="fc-field">Tus preferencias<textarea rows="4" data-field="preferences" placeholder="Por ejemplo: gris, limpio y fácil de leer…">${safe(state.preferences)}</textarea></label><div class="fc-actions">${button('Guardar preferencias','preferences-save','check',true)}</div>`;
      else if(state.view==='worker')html+=`<h3>${a.workers[state.worker||0]}</h3><p>Un encargo concreto, con un resultado que se pueda revisar.</p><details class="fc-sheet" open><summary class="cursor-interaction">Ficha del trabajador</summary><dl><dt>Necesita</dt><dd>${a.needs}</dd><dt>Entregará</dt><dd>${a.delivery}</dd><dt>Revisa</dt><dd>Su coordinador y calidad cuando corresponda.</dd><dt>Estado</dt><dd>Preparado. Sin ejecución real.</dd></dl></details><div class="fc-actions">${button('Ver el circuito de revisión','review','scan-line',true)}${button('Volver a su coordinador','back','arrow-left')}</div>`;
      else html+=`<h3>${i===0?'Primero, una dirección.':i===1?'Cada acción, un resultado.':'Comprobar antes de cerrar.'}</h3><p>${a.task}</p><details class="fc-sheet" open><summary class="cursor-interaction">Plan del departamento</summary><dl><dt>Necesita</dt><dd>${a.needs}</dd><dt>Entregará</dt><dd>${a.delivery}</dd><dt>Comprueba</dt><dd>${a.test}</dd></dl></details><div class="fc-actions">${i===0?button('Conocer tus preferencias','preferences','sliders-horizontal'):button('Aclarar este encargo','clarify','messages-square')}${button(state.approved[i]?'Reabrir esta área':'Apruebo esta área','approve',state.approved[i]?'pencil':'check',true)}</div><p class="fc-fine">Los trabajadores aparecen cuando todas las áreas están aprobadas.</p>`;
    }
    if(state.notice&&state.view!=='ideas')html+=`<div class="fc-notice" role="status">${safe(state.notice)}</div>`;
    panel.innerHTML=html;panel.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>{if(!tour.playing)dispatch(b.dataset.act)});if(state.view==='ideas')bindSwipe();icons();}
    let swiping=false;
    function bindSwipe(){const card=q('.fc-idea-card');if(!card||!available().length)return;let start=null,dx=0;card.addEventListener('pointerdown',e=>{if(tour.playing||swiping)return;e.preventDefault();start={x:e.clientX,y:e.clientY};dx=0;card.setPointerCapture(e.pointerId)});card.addEventListener('pointermove',e=>{if(!start)return;dx=e.clientX-start.x;const dy=e.clientY-start.y;if(Math.abs(dx)<Math.abs(dy)&&Math.abs(dy)>15){start=null;return}card.style.transform=`translateX(${dx}px) rotate(${dx/15}deg)`;const label=card.querySelector('.fc-swipe-label');label.textContent=dx>0?'AÑADIR':'DESCARTAR';label.style.opacity=String(Math.min(Math.abs(dx)/100,.95));label.style.left=dx>0?'17px':'auto';label.style.right=dx<0?'17px':'auto'});const release=()=>{if(!start)return;start=null;if(Math.abs(dx)>70)choose(dx>0);else{card.style.transition='transform .25s';card.style.transform='';card.querySelector('.fc-swipe-label').style.opacity='0'}};card.addEventListener('pointerup',release);card.addEventListener('pointercancel',()=>{start=null;card.style.transform='';card.querySelector('.fc-swipe-label').style.opacity='0'})}
    async function choose(accept,animate=true){if(swiping)return;const card=available()[0];if(!card)return;const tokenAtStart=tour.token,fromTour=tour.open;swiping=true;const node=q('.fc-idea-card');if(node&&animate&&!reduce()){node.style.transition='transform .35s cubic-bezier(.2,.7,.3,1),opacity .3s';node.style.transform=`translateX(${accept?400:-400}px) rotate(${accept?22:-22}deg)`;node.style.opacity='0';await wait(330)}if(fromTour&&tokenAtStart!==tour.token){swiping=false;return}if(accept){state.added.push(card);if(state.phase){state.phase=0;state.approved=[false,false,false];state.versionsConfirmed=false}state.notice='Añadida a tu idea: '+card.title}else{state.discarded.push(card.id);state.notice='Descartada. Vamos con otra posibilidad.'}swiping=false;renderPanel();const next=q('.fc-idea-card');if(next&&animate&&!reduce()){next.animate([{transform:'translateY(12px) scale(.97)',opacity:.6},{transform:'translateY(0) scale(1)',opacity:1}],{duration:280,easing:'ease-out'})}save()}
    function dispatch(act){state.notice='';if(act==='develop'){const value=q('[data-field="idea"]')?.value.trim()||state.idea;if(!value){state.notice='Escribe una frase sobre lo que quieres crear.';renderPanel();return}if(value!==state.idea){state.added=[];state.discarded=[];state.phase=0;state.approved=[false,false,false];state.versionsConfirmed=false}state.idea=value;state.topic=identify(value);state.view='questions';}
      else if(act==='ideas'){const draft=q('[data-field="idea"]')?.value.trim();if(draft){state.idea=draft;state.topic=identify(draft)}state.view='ideas'}
      else if(act==='edit')state.view='start';else if(act==='questions')state.view='questions';else if(act==='back'){state.view='overview'}
      else if(act==='answer'){const value=q('[data-field="answer"]')?.value.trim();if(!value){state.notice='Escribe una respuesta para concretar el plan.';renderPanel();return}if(state.answer&&value!==state.answer){state.phase=0;state.approved=[false,false,false];state.versionsConfirmed=false}state.answer=value;state.view='overview'}
      else if(act==='accept'){choose(true);return}else if(act==='discard'){choose(false);return}
      else if(act==='plan'){if(!state.idea){state.notice='Primero escribe qué quieres crear.';renderPanel();return}state.view='plan'}
      else if(act==='team'){if(!state.answer){state.notice='Nos falta aclarar cómo se utilizará. Vuelve y responde la pregunta.';renderPanel();return}state.phase=1;state.selected=0;state.view='overview'}
      else if(act==='preferences')state.view='preferences';else if(act==='preferences-save'){state.preferences=q('[data-field="preferences"]')?.value.trim()||'';state.view='overview';state.notice='Preferencias guardadas en tu proyecto.'}
      else if(act==='clarify')state.notice='Aquí el coordinador preguntará por los puntos de su área que todavía falten por concretar.';
      else if(act==='versions'){state.selected='super';state.view='versions'}
      else if(act==='versions-save'){const count=Number(q('[data-field="versions"]').value);if(!Number.isInteger(count)||count<1||count>10){state.notice='Elige entre 1 y 10 propuestas para este prototipo.';renderPanel();return}state.versions=count;state.variation=q('[data-field="variation"]').value.trim()||'Diseño y distribución';state.versionsConfirmed=true;state.view='overview';state.notice=`Has elegido ${count} propuesta${count===1?'':'s'}. Ya puedes consultar los trabajadores y exportar el equipo.`}
      else if(act==='approve'){state.approved[state.selected]=!state.approved[state.selected];if(state.approved.every(Boolean)){state.selected='super';state.view='versions';state.notice='Las áreas están aprobadas. Antes de ejecutar, decide cuántas propuestas quieres explorar.'}else{state.versionsConfirmed=false;state.notice='Área actualizada.'}}

      else if(act==='review'){state.selected='super';state.result='issue';state.view='result'}else if(act==='fix'){state.result='fixed'}else if(act==='verify'){state.result='done'}
      render();save();}
    const demoSteps=[
      {title:'Empieza con tu propia idea.',desc:'El alumno escribe una frase. El equipo todavía está bloqueado.',view:'start',target:'[data-field="idea"]',typing:'Quiero una web para organizar torneos entre mis amigos.'},
      {title:'La idea dirige la pregunta.',desc:'En este recorrido, el supercoordinador aclara cómo se apuntarán los participantes.',view:'questions',target:'[data-field="answer"]',typing:'Se apuntarán solos desde el móvil. Somos unos 16 amigos.'},
      {title:'Pide ideas cuando te quedes en blanco.',desc:'Se abre un mazo de recomendaciones relacionadas con los torneos.',view:'ideas',target:'.fc-idea-card'},
      {title:'Descarta lo que no encaje.',desc:'Una clasificación pública complica la primera versión. El alumno la deja pasar.',view:'ideas',target:'[data-act="discard"]',decision:false},
      {title:'Añade lo que sí te aporte.',desc:'Los recordatorios ayudan a que nadie se pierda una partida. Se incorporan al plan.',view:'ideas',target:'[data-act="accept"]',decision:true},
      {title:'Revisa los cimientos antes de repartir.',desc:'La idea y la recomendación aceptada quedan juntas en el plan.',view:'plan',target:'[data-act="team"]'},
      {title:'Se desbloquean los coordinadores.',desc:'El proyecto tiene tres áreas esenciales. El equipo real se adaptará a su magnitud.',phase:1,selected:0,view:'overview',target:'[data-node="0"]'},
      {title:'Diseño conoce tus preferencias.',desc:'El alumno explica la dirección visual antes de repartir las tareas.',phase:1,selected:0,view:'preferences',target:'[data-field="preferences"]',typing:'Grises suaves, tipografía clara y una inscripción muy sencilla.'},
      {title:'Aprueba el plan de diseño.',desc:'El coordinador preparará los encargos de pantallas, colores y tipografía.',phase:1,selected:0,view:'overview',target:'[data-act="approve"]',approval:0},
      {title:'Concreta qué debe funcionar.',desc:'El área de funcionamiento asume la creación de torneos y la inscripción.',phase:1,selected:1,view:'overview',target:'[data-act="approve"]',approval:1},
      {title:'Define cómo se comprobará.',desc:'Calidad revisará los botones, las validaciones y el recorrido completo.',phase:1,selected:2,view:'overview',target:'[data-act="approve"]',approval:2},
      {title:'Los trabajadores reciben sus encargos.',desc:'Con todas las áreas aprobadas, cada trabajador tiene su tarea y su entrega.',phase:1,selected:1,view:'worker',target:'[data-worker="1-0"]'},
      {title:'Calidad encuentra un defecto.',desc:'En esta simulación, el formulario permite enviar una inscripción sin nombre.',phase:1,selected:'super',view:'result',result:'issue',target:'[data-act="fix"]'},
      {title:'Corregir y volver a comprobar.',desc:'Funcionamiento corrige el problema y calidad repite la prueba.',phase:1,selected:'super',view:'result',result:'fixed',target:'[data-act="verify"]'},
      {title:'El supercoordinador reúne el resultado.',desc:'La demostración termina con las partes revisadas. El alumno conserva la decisión final.',phase:1,selected:'super',view:'result',result:'done',target:'.fc-panel h3'}
    ];
    demoSteps.splice(11,0,{title:'Elige cuántas propuestas explorar.',desc:'Con las áreas aprobadas, el supercoordinador pregunta cuántas versiones deseas y qué debe variar.',phase:1,selected:'super',view:'versions',target:'[data-act="versions-save"]',confirmVersions:true});
    demoSteps.push({title:'El equipo está listo para exportar.',desc:'Descarga el plan y los encargos para ChatGPT o Claude. Exportar no inicia agentes ni conecta conversaciones.',phase:1,selected:'super',view:'result',result:'done',target:'[data-act="export"]'});
    function applyStep(index){const s=demoSteps[index];state.idea='Quiero una web para organizar torneos entre mis amigos.';state.topic='torneo';state.answer=index>1?'Se apuntarán solos desde el móvil. Somos unos 16 amigos.':'';state.phase=s.phase||0;state.selected=s.selected??'super';state.view=s.view;state.notice='';state.added=index>4?[banks.torneo[1]]:[];state.discarded=index>3?['t1']:[];state.approved=[index>8,index>9,index>10];state.worker=0;state.versions=2;state.versionsConfirmed=index>11;state.result=s.result||'';if(index===4)state.discarded=['t1'];render();}
    function renderTour(){q('.fc-tourbar').hidden=!tour.open;q('.fc-demo-cursor').hidden=!tour.open||!tour.playing;if(!tour.open)return;const s=demoSteps[tour.index];q('.fc-tour-number').textContent=String(tour.index+1).padStart(2,'0');q('.fc-tour-title').textContent=s.title;q('.fc-tour-description').textContent=s.desc;q('.fc-tour-position').textContent=`${tour.index+1} / ${demoSteps.length}`;q('[data-act="tour-play"]').textContent=tour.playing?'Pausar':tour.index===demoSteps.length-1?'Repetir':'Reproducir';q('[data-act="tour-prev"]').disabled=tour.index===0;q('[data-act="tour-next"]').disabled=tour.index===demoSteps.length-1;q('.fc-tour-track div').style.width=((tour.index+1)/demoSteps.length*100)+'%';}
    function moveCursor(selector){const target=q(selector);if(!target)return;const a=app.getBoundingClientRect(),b=target.getBoundingClientRect();q('.fc-demo-cursor').style.transform=`translate(${Math.max(10,b.left-a.left+b.width*.65)}px,${Math.max(10,b.top-a.top+Math.min(b.height/2,40))}px)`;}
    async function perform(token){const s=demoSteps[tour.index];if(token!==tour.token||!tour.playing)return;moveCursor(s.target);await wait(reduce()?100:750);if(token!==tour.token||!tour.playing)return;
      if(s.typing){const field=q(s.target);if(field){field.value='';for(let i=1;i<=s.typing.length;i+=reduce()?s.typing.length:2){if(token!==tour.token||!tour.playing)return;field.value=s.typing.slice(0,i);await wait(reduce()?0:22)}field.value=s.typing;}}
      if(s.decision!==undefined){await choose(s.decision);}
      if(s.approval!==undefined){state.approved[s.approval]=true;renderMap();renderPanel();}if(s.confirmVersions){state.versionsConfirmed=true;renderMap();}q('[data-act="export"]').disabled=!state.approved.every(Boolean)||!state.versionsConfirmed;
      if(token!==tour.token||!tour.playing)return;const target=q(s.target);if(target){target.classList.add('fc-click-flash');await wait(250);target.classList.remove('fc-click-flash')}
      await wait(1600);if(token!==tour.token||!tour.playing)return;if(tour.index<demoSteps.length-1){tour.index++;applyStep(tour.index);perform(token)}else{tour.playing=false;renderTour()}}
    function stop(){tour.playing=false;tour.token++;renderTour()}
    function tourAction(action){if(action==='tour'){if(!tour.open){tour.snapshot=JSON.parse(JSON.stringify(state));const draft=q('[data-field="idea"]')?.value;if(draft){tour.snapshot.idea=draft;tour.snapshot.topic=identify(draft)}tour.open=true;tour.index=0;applyStep(0);}tour.playing=true;const token=++tour.token;renderTour();perform(token)}
      else if(action==='close-tour'){stop();tour.open=false;if(tour.snapshot)Object.assign(state,tour.snapshot);render()}
      else if(action==='tour-play'){if(tour.playing){stop();return}if(tour.index===demoSteps.length-1)tour.index=0;applyStep(tour.index);tour.playing=true;const token=++tour.token;renderTour();perform(token)}
      else if(action==='tour-next'||action==='tour-prev'){stop();tour.index=Math.max(0,Math.min(demoSteps.length-1,tour.index+(action==='tour-next'?1:-1)));applyStep(tour.index);}}
    root.querySelectorAll('.fc-header [data-act],.fc-tourbar [data-act]').forEach(b=>b.onclick=()=>b.dataset.act==='export'?openExport():tourAction(b.dataset.act));
    q('.fc-brand').onclick=e=>{e.preventDefault();if(tour.playing)return;state.selected='super';state.view=state.idea?'overview':'start';render()};
    try{const saved=JSON.parse(localStorage.getItem('forma-project-v1')||'null');if(saved&&typeof saved.idea==='string'&&Array.isArray(saved.approved)&&saved.approved.length===3){Object.assign(state,saved);state.approved=saved.approved.map(Boolean);state.phase=saved.phase===1?1:0;state.versions=Number.isInteger(saved.versions)&&saved.versions>=1&&saved.versions<=10?saved.versions:1;state.added=Array.isArray(saved.added)?saved.added.filter(x=>x&&typeof x.id==='string'&&typeof x.title==='string'):[];state.discarded=Array.isArray(saved.discarded)?saved.discarded:[];state.selected='super';state.view=state.idea?'overview':'start';state.topic=identify(state.idea);state.notice='';}}
    catch{}
    render();
    function exportData(){
      return {schema:'forma.team/1',generated_at:new Date().toISOString(),target:state.exportTarget,project:{idea:state.idea,clarifications:state.answer,preferences:state.preferences,accepted_ideas:state.added.map(x=>({title:x.title,description:x.text})),proposals:{count:state.versions,vary:state.variation,combination:'El usuario puede elegir o combinar propuestas. Toda combinación necesita revisión.'}},supercoordinator:{id:'supercoordinador',role:'Desarrollar y mantener el plan, resolver dependencias, integrar y aceptar contra criterios.'},departments:areas.map((a,i)=>({id:['diseno','funcionamiento','calidad'][i],name:a.name,approved:state.approved[i],objective:a.task,inputs:a.needs,deliverable:a.delivery,acceptance:a.test,workers:a.workers.map((name,j)=>({id:`${['diseno','funcionamiento','calidad'][i]}-${j+1}`,name,coordinator:['diseno','funcionamiento','calidad'][i]}))})),status:'PLAN_PREPARADO_NO_EJECUTADO',limits:{runtime:'Exportar no crea ni ejecuta conversaciones.',communication:'Debe configurarse un canal compatible y autorizado o trasladar manualmente los informes.',scope:'El reparto y las recomendaciones provienen de este prototipo, no de una generación con IA.'}};
    }
    function commonPlan(){return `PLAN COMÚN — FORMA\n\nIDEA\n${state.idea}\n\nACLARACIONES DEL USUARIO\n${state.answer}\n\nPREFERENCIAS DE DISEÑO\n${state.preferences||'Todavía no indicadas. Preguntar cuando sea necesario.'}\n\nIDEAS ACEPTADAS\n${state.added.length?state.added.map(x=>`- ${x.title} ${x.text}`).join('\n'):'No se han añadido recomendaciones.'}\n\nPROPUESTAS\nPreparar ${state.versions} propuesta${state.versions===1?'':'s'}. Variar: ${state.variation}. Mantener iguales los requisitos obligatorios. El usuario puede seleccionar o combinar; revisar la compatibilidad de cualquier mezcla antes de aceptarla.\n\nÁREAS APROBADAS\n${areas.map(a=>`- ${a.name}: ${a.task} Entrega: ${a.delivery} Comprobación: ${a.test}`).join('\n')}\n\nANTES DE EJECUTAR\nEste paquete prepara encargos; no demuestra implementación ni pruebas. Revisa con el usuario el alcance, las rutas de trabajo, los contratos entre áreas, los criterios observables de aceptación y los límites de gasto, tiempo y revisiones. No inventes datos ni autorizaciones.\n\nREGLAS\nTrabajar en copias o ámbitos separados. Un responsable por cambio. Calidad registra defectos; el área responsable corrige; calidad repite la comprobación. El supercoordinador integra y contrasta el conjunto. No rebajar criterios ni cambiar el objetivo para aprobar una entrega.\n\nCOMUNICACIÓN\nConfigurar destinatarios y canal real antes de delegar. Un informe indica emisor, destinatario, revisión, tarea, resultado, evidencia, dependencia y siguiente acción. Si no existe canal entre conversaciones, producir informes autocontenidos para traslado manual.\n\nCIERRE\nPASS / FAIL / NOT_RUN / BLOCKED por criterio. Separar análisis, simulación y ejecución real. Si se repite un bloqueo sin progreso o se alcanza un límite, explicar el estado y pedir una decisión. El usuario conserva el visto bueno final.\n`;}
    function launchPrompt(){return `Actúa como supercoordinador del proyecto descrito en PLAN_COMUN.txt y equipo.json.\n\nLee primero esos archivos y los encargos. Resume lo aprobado y señala los datos imprescindibles que faltan antes de ejecutar. No afirmes que las conversaciones ya existen.\n\n${state.exportTarget==='claude'?'Si estás en Claude Code y existe un sistema de agentes compatible, comprueba primero su disponibilidad, permisos y canal. Las definiciones en .claude/agents/ son roles para reutilizar; no garantizan una jerarquía de agentes anidados ni crean chats en claude.ai. Si estás en el chat habitual de Claude, guía al usuario para abrir las conversaciones y trasladar sus informes.':'En los chats habituales de ChatGPT, utiliza el plan y los prompts para iniciar conversaciones separadas. No presupongas mensajería entre chats. Si trabajas en otro entorno con herramientas de agentes, confirma sus capacidades y permisos antes de delegar.'}\n\nPrepara ${state.versions} propuesta${state.versions===1?'':'s'} variando ${state.variation}. Mantén los requisitos comunes. Comunica dependencias y revisiones por un canal real. No inicies acciones externas, publicaciones ni consumo ilimitado sin la autorización correspondiente.\n\nEmpieza comprobando el plan y pregunta solo lo que falte para poder trabajar de forma verificable.\n`;}
    function rolePrompt(type,index,workerIndex){const base='Lee PLAN_COMUN.txt y equipo.json. Si no puedes acceder a esos archivos, pide su contenido. No presupongas el historial de otras conversaciones.\n\n';
      if(type==='super')return base+launchPrompt();
      const a=areas[index];
      if(type==='coordinator')return base+`Eres el coordinador de ${a.name}.\n\nObjetivo: ${a.task}\nEntradas: ${a.needs}\nEntrega del área: ${a.delivery}\nCriterio inicial: ${a.test}\n\nAntes de trabajar, concreta los criterios verificables, el ámbito de escritura y el canal. ${index===0?'Pregunta por las preferencias que falten sin repetir lo ya confirmado. Respeta la ficha de diseño. ':''}Prepara encargos para: ${a.workers.join(' y ')}. Ajusta su alcance con el supercoordinador si hace falta; no amplíes unilateralmente el proyecto.\n\nRevisa las entregas, comunica dependencias y registra revisiones. Si algo falla, emite una corrección con esperado, observado, responsable y prueba. ${index===2?'Mantén independencia: registra el defecto para el área responsable y verifica su corrección.':'Entrega a calidad lo necesario para comprobar el trabajo.'}\n\nNo necesitas un agente adicional para cada nombre si el entorno no lo permite. Conserva los roles y límites, y comunica al supercoordinador cualquier adaptación.\n`;
      return base+`Eres el trabajador de ${a.workers[workerIndex]}, del área ${a.name}.\n\nPide al coordinador un encargo concreto: qué haces, qué necesitas, qué entregas y cómo se comprueba. Respeta el alcance aprobado y no modifiques el trabajo de otros sin acuerdo.\n\nReferencia de área: ${a.task}\nEntrega del área: ${a.delivery}\n\nTrabaja solo sobre el ámbito asignado. Si dependes de otra entrega, solicítala por el canal autorizado. No inventes el resultado. Entrega una revisión identificada, cambios o documentos, pruebas pertinentes, límites y bloqueos. Una corrección debe conservar la revisión anterior y repetir la comprobación afectada.\n\nDistingue lo preparado de lo realmente ejecutado. No certifiques la integración global.\n`;
    }
    function bundleFiles(){const target=state.exportTarget;const readme=`FORMA — EQUIPO EXPORTADO PARA ${target==='claude'?'CLAUDE':'CHATGPT'}\n\n1. Lee PLAN_COMUN.txt y revisa equipo.json.\n2. Inicia la conversación principal con INICIAR_AQUI.txt y adjunta los archivos.\n3. Revisa los datos y límites pendientes antes de ejecutar.\n4. Abre o configura las conversaciones de coordinadores según las capacidades reales del entorno. Usa el encargo correspondiente en prompts/.\n5. Comparte el mismo plan con todos. Activa los trabajadores después de confirmar sus ámbitos y canal.\n6. Los coordinadores revisan; las áreas responsables corrigen; calidad verifica; el supercoordinador reúne el conjunto.\n\nIMPORTANTE\nEsta descarga no importa chats automáticamente ni conecta agentes. Los chats web habituales requieren traslado manual de informes salvo que exista una integración compatible. ${target==='claude'?'Las definiciones .claude/agents/ pueden reutilizarse en Claude Code, pero no constituyen un importador de claude.ai ni garantizan agentes anidados.':'Los prompts pueden usarse en conversaciones separadas de ChatGPT; no crean chats mediante un API ni activan mensajería por sí solos.'}\n\nEste es un paquete de planificación generado por un prototipo sin IA conectada. Los departamentos y las recomendaciones deben revisarse antes de usarse. Ningún resultado de la aplicación ha sido ejecutado por descargarlo.\n\nNo se incluyen credenciales. Define permisos, tiempo, presupuesto y número máximo de revisiones antes de automatizar.\n`;
      const files={'LEEME.txt':readme,'PLAN_COMUN.txt':commonPlan(),'equipo.json':JSON.stringify(exportData(),null,2),'INICIAR_AQUI.txt':launchPrompt(),'prompts/00_supercoordinador.txt':rolePrompt('super')};
      areas.forEach((a,i)=>{const slug=['diseno','funcionamiento','calidad'][i];files[`prompts/${i+1}0_coordinador_${slug}.txt`]=rolePrompt('coordinator',i);a.workers.forEach((name,j)=>files[`prompts/${i+1}${j+1}_trabajador_${slug}.txt`]=rolePrompt('worker',i,j));});
      if(target==='claude'){files['CLAUDE.md']='# Proyecto preparado en Forma\n\nLee PLAN_COMUN.txt, equipo.json e INICIAR_AQUI.txt antes de trabajar. Comprueba el entorno, la autorización y los criterios pendientes. La exportación no inicia agentes.\n';areas.forEach((a,i)=>{const slug=['diseno','funcionamiento','calidad'][i];files[`.claude/agents/coordinador-${slug}.md`]=`---\nname: coordinador-${slug}\ndescription: Coordina el área de ${a.name.toLowerCase()} del plan aprobado.\n---\n\n${rolePrompt('coordinator',i)}`;a.workers.forEach((w,j)=>files[`.claude/agents/trabajador-${slug}-${j+1}.md`]=`---\nname: trabajador-${slug}-${j+1}\ndescription: Trabaja en ${w.toLowerCase()} dentro del ámbito asignado.\n---\n\n${rolePrompt('worker',i,j)}`);});}
      return files;
    }
    function renderExport(){const files=bundleFiles();q('.fc-export-summary').textContent=`${state.exportTarget==='claude'?'Claude':'ChatGPT'} · 1 supercoordinador · 3 coordinadores · 6 encargos de trabajadores · ${state.versions} propuesta${state.versions===1?'':'s'}`;q('.fc-export-files').replaceChildren();Object.keys(files).forEach(name=>{const li=document.createElement('li');li.textContent=name;q('.fc-export-files').append(li)});qa('[data-target]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.target===state.exportTarget)));q('.fc-export-status').textContent='';}
    function openExport(){if(!state.phase||!state.approved.every(Boolean)||!state.versionsConfirmed)return;renderExport();q('.fc-export-dialog').showModal();}
    qa('[data-target]').forEach(b=>b.onclick=()=>{state.exportTarget=b.dataset.target;renderExport();save()});
    q('[data-export-act="close"]').onclick=()=>q('.fc-export-dialog').close();
    q('[data-export-act="download"]').onclick=async()=>{const status=q('.fc-export-status');const button=q('[data-export-act="download"]');try{button.disabled=true;status.textContent='Preparando el paquete…';const zip=new JSZip();Object.entries(bundleFiles()).forEach(([name,text])=>zip.file(name,text));const blob=await zip.generateAsync({type:'blob',compression:'DEFLATE'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`forma-equipo-${state.exportTarget}.zip`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);status.textContent='Paquete preparado. Consulta LEEME.txt para empezar.'}catch{status.textContent='No se pudo preparar la descarga. Inténtalo de nuevo.'}finally{button.disabled=false}};
    q('[data-export-act="copy"]').onclick=async()=>{try{await navigator.clipboard.writeText(launchPrompt());q('.fc-export-status').textContent='Instrucción copiada. Acompáñala con el plan y los encargos.'}catch{q('.fc-export-status').textContent='El navegador no permite copiar. Descarga el paquete y abre INICIAR_AQUI.txt.'}};

  })();